type Sleeper interface {
    Sleep(ctx context.Context, duration time.Duration) error
}

type TransientError struct {
    Err        error
    RetryAfter time.Duration
}

func (e *TransientError) Error() string {
    return e.Err.Error()
}

func (e *TransientError) Unwrap() error {
    return e.Err
}

type Config struct {
    MaxAttempts int
    BaseDelay   time.Duration
}

type Dependencies struct {
    Sleeper Sleeper
}

type Retrier struct {
    config Config
    sleeper Sleeper
}

func New(config Config, deps Dependencies) (*Retrier, error) {
    if config.MaxAttempts < 1 {
        return nil, fmt.Errorf("retry: MaxAttempts must be >= 1, got %d", config.MaxAttempts)
    }
    if config.BaseDelay < 0 {
        return nil, fmt.Errorf("retry: BaseDelay must be >= 0, got %v", config.BaseDelay)
    }
    sleeper := deps.Sleeper
    if sleeper == nil {
        sleeper = &clockSleeper{}
    }
    return &Retrier{
        config:  config,
        sleeper: sleeper,
    }, nil
}

type clockSleeper struct{}

func (s *clockSleeper) Sleep(ctx context.Context, d time.Duration) error {
    select {
    case <-ctx.Done():
        return ctx.Err()
    case <-time.After(d):
        return nil
    }
}

